// Capas vectoriales, iconos oficiales y rotulos extraidos 1:1 de los planos DGIU UAA
// Incluye banos, casetas de vigilancia, estacionamientos (E), cafeterias, bibliotecas, auditorios y bandera.

// Tipos de pictogramas oficiales presentes en la simbologia del mapa DGIU
enum TipoIconoMapaUaa {
  sanitarios,
  vigilancia,
  estacionamiento,
  cafeteria,
  biblioteca,
  auditorio,
}

// Pictograma vectorial posicionado en coordenadas exactas sobre el plano
class IconoVectorialMapa {
  final TipoIconoMapaUaa tipo;
  final double posX;
  final double posY;

  const IconoVectorialMapa(this.tipo, this.posX, this.posY);
}

// Etiqueta vectorial de vialidad, infraestructura o punto de referencia oficial del mapa
class EtiquetaVectorialMapa {
  final String texto;
  final double posX;
  final double posY;
  final double anguloGrados;
  final double tamanoFuente;
  final bool esVialidad;

  const EtiquetaVectorialMapa({
    required this.texto,
    required this.posX,
    required this.posY,
    this.anguloGrados = 0.0,
    this.tamanoFuente = 9.0,
    this.esVialidad = false,
  });
}

